import {CUMULATIVE_PROMPT_KEYS,cumulativePromptDefault} from '../shared/settings/cumulative-prompts.js';
const copy=value=>structuredClone(value);
export function createCumulativeSettingsController({settings,exclusions,isCurrent=()=>true,onBack=()=>{},onClose=()=>{},onOpenCleaning=()=>{}}={}){
  const listeners=new Set();let disposed=false,busy=false,baseline=null;
  const state={status:'loading',target:null,draft:null,promptDrafts:{},excludedFloors:[],opened:{},scroll:{},message:'',error:null,savedSequence:0,injectionDraft:null,floorDraft:''};
  const inspect=()=>copy(state),notify=()=>{if(!disposed)for(const listener of [...listeners])try{listener(inspect());}catch{/* view only */}};
  const current=()=>{try{return !disposed&&isCurrent()===true;}catch{return false;}};
  const fail=error=>{state.status=error?.code==='SETTINGS_COMMIT_UNCONFIRMED'||error?.code==='COMMIT_UNCONFIRMED'?'unconfirmed':'error';state.error=error?.code??'SETTINGS_CONFLICT';state.message=state.status==='unconfirmed'?'保存结果尚未确认，请重新读取，不要重复提交。':error?.message??'设置已变化，请重新读取。';};
  function editable(){if(busy||disposed||state.status!=='ready'||!baseline)return false;if(!current()||!settings.matchesCumulativeGeneration(baseline)){fail(new Error('设置或聊天已变化，请重新读取。'));notify();return false;}return true;}
  async function load(preserve=false,useConfirmed=false){if(disposed||busy)return false;busy=true;state.status='loading';notify();try{let captured=null;if(useConfirmed){try{captured=settings.captureCumulativeGeneration();}catch{/* Explicit read if authority is unavailable. */}}if(!captured)await settings.read();if(!current())throw new Error('聊天已变化，请重新读取。');captured??=settings.captureCumulativeGeneration();if(!settings.matchesCumulativeGeneration(captured))throw new Error('设置已变化，请重新读取。');baseline=captured;state.draft=copy(captured.generation);if(!preserve){state.promptDrafts={};state.injectionDraft=null;}state.status='ready';state.error=null;state.message='';notify();const floors=await exclusions.read();if(!current()||!settings.matchesCumulativeGeneration(captured))throw new Error('聊天或设置已变化，请重新读取。');state.excludedFloors=copy(floors);return true;}catch(error){fail(error);return false;}finally{busy=false;notify();}}
  async function commit(change,adopt=()=>{}){if(!editable())return false;const draft=copy(baseline.generation),epoch=baseline.epoch;try{change(draft);}catch(error){state.error='INVALID_SETTINGS';state.message=error.message;notify();return false;}busy=true;state.status='saving';state.error=null;state.message='';notify();try{if(!current())throw new Error('聊天已变化，请重新读取。');await settings.saveCumulativeGeneration(draft,{expectedEpoch:epoch,isCurrent:current});if(!current())throw new Error('聊天已变化，请重新读取。');baseline=settings.captureCumulativeGeneration();state.draft=copy(baseline.generation);adopt();state.status='ready';state.error=null;state.message='已保存';state.savedSequence++;return true;}catch(error){fail(error);return false;}finally{busy=false;notify();}}
  async function floor(action,value){if(!editable())return false;const n=typeof value==='string'&&!value.trim()?NaN:Number(value);if(!Number.isSafeInteger(n)||n<0){state.error='INVALID_FLOOR';state.message='请输入大于或等于0的整数楼层。';notify();return false;}busy=true;state.status='saving';state.error=null;state.message='';notify();try{await exclusions[action](n);if(!current())throw new Error('聊天已变化，请重新读取。');state.excludedFloors=copy(await exclusions.read());if(!current())throw new Error('聊天已变化，请重新读取。');state.status='ready';state.error=null;state.floorDraft='';state.message='已保存';state.savedSequence++;return true;}catch(error){fail(error);return false;}finally{busy=false;notify();}}
  const off=settings.subscribe?.(()=>{if(!busy&&baseline&&state.status==='ready'&&(!current()||!settings.matchesCumulativeGeneration(baseline))){fail(new Error('设置已变化，请重新读取。'));notify();}});
  const controller={inspect,init(){if(baseline)return Promise.resolve(editable());return load(false,true);},read:()=>load(true),
    editPrompt(key,value){if(!CUMULATIVE_PROMPT_KEYS.includes(key)||typeof value!=='string'||!editable())return false;state.promptDrafts[key]=value;state.message='';return true;},
    restorePrompt(key){return controller.editPrompt(key,cumulativePromptDefault(key));},
    savePrompt(key){if(!Object.hasOwn(state.promptDrafts,key)||!CUMULATIVE_PROMPT_KEYS.includes(key))return Promise.resolve(false);const value=state.promptDrafts[key];return commit(draft=>{draft.promptOverrides={...draft.promptOverrides,[key]:value};},()=>{delete state.promptDrafts[key];});},
    cancelPrompt(key){if(!editable())return false;delete state.promptDrafts[key];notify();return true;},
    editInjection(value){if(!editable())return false;state.injectionDraft=value;return true;},
    saveInjection(){const value=state.injectionDraft??state.draft?.injectionPosition??9999;return commit(draft=>{const n=typeof value==='string'&&!value.trim()?NaN:Number(value);if(!Number.isSafeInteger(n)||n<0)throw new Error('请输入大于或等于0的整数深度。');draft.injectionPosition=n;},()=>{state.injectionDraft=null;});},
    setFloorDraft(value){state.floorDraft=value;},addFloor:value=>floor('add',value),removeFloor:value=>floor('remove',value),
    openCleaning(){if(!editable())return false;onOpenCleaning({origin:'cumulative',onBack:()=>{notify();}});return true;},
    back(){if(busy)return false;state.promptDrafts={};state.injectionDraft=null;onBack();return true;},close(){onClose();},
    setScroll(key,value){state.scroll[key]=value;},setOpen(key,value){state.opened[key]=!!value;},subscribe(listener){listeners.add(listener);return()=>listeners.delete(listener);},dispose(){disposed=true;off?.();listeners.clear();}
  };return Object.freeze(controller);
}
